static WiFiClient net;static PubSubClient mq(net);static WiFiManager wm;ESPManagerClass ESPManager;static String base(){return String("espmanager/")+ESPMANAGER_DEVICE_ID;}static void rx(char*t,byte*p,unsigned n){String s;for(unsigned i=0;i<n;i++)s+=(char)p[i];ESPManager.command(t,s);}void ESPManagerClass::add(E e){if(ec<48)es[ec++]=e;if(mq.connected())discover();}void ESPManagerClass::onCommand(Handler h){handler=h;}void ESPManagerClass::registerSensor(const char*i,const char*n,const char*u,const char*un,const char*d,const char*s,const char*v){E e;e.t="sensor";e.id=i;e.n=n;e.u=u;e.unit=un;e.dc=d;e.sc=s;e.vt=v;add(e);}void ESPManagerClass::registerBinarySensor(const char*i,const char*n,const char*u,const char*d){E e;e.t="binary_sensor";e.id=i;e.n=n;e.u=u;e.dc=d;add(e);}void ESPManagerClass::registerSwitch(const char*i,const char*n,const char*u){E e;e.t="switch";e.id=i;e.n=n;e.u=u;add(e);}void ESPManagerClass::registerNumber(const char*i,const char*n,const char*u,float lo,float hi,float st,const char*un){E e;e.t="number";e.id=i;e.n=n;e.u=u;e.lo=lo;e.hi=hi;e.step=st;e.unit=un;add(e);}void ESPManagerClass::registerCover(const char*i,const char*n,const char*u,bool p){E e;e.t="cover";e.id=i;e.n=n;e.u=u;e.pos=p;add(e);}bool ESPManagerClass::publishState(const char*i,const String&v,bool r){return mq.connected()&&mq.publish((base()+"/state/"+i).c_str(),v.c_str(),r);}void ESPManagerClass::publishSensor(const char*i,double v){char b[32];snprintf(b,sizeof(b),"%.3f",v);mq.publish((base()+"/sensor/"+i).c_str(),b,true);}void ESPManagerClass::discover(){for(uint8_t k=0;k<ec;k++){auto&e=es[k];JsonDocument d;d["name"]=e.n;d["unique_id"]=e.u;d["state_topic"]=base()+"/state/"+e.id;d["availability_topic"]=base()+"/availability";if(e.unit.length())d["unit_of_measurement"]=e.unit;if(e.dc.length())d["device_class"]=e.dc;if(e.sc.length())d["state_class"]=e.sc;if(e.vt.length())d["value_template"]=e.vt;if(e.t=="switch"||e.t=="number"||e.t=="cover")d["command_topic"]=base()+"/cmd/entity/"+e.id;if(e.t=="number"){d["min"]=e.lo;d["max"]=e.hi;d["step"]=e.step;}if(e.t=="cover"&&e.pos){d["position_topic"]=base()+"/state/"+e.id+"_position";d["set_position_topic"]=base()+"/cmd/entity/"+e.id+"_position";}JsonArray ids=d["device"]["identifiers"].to<JsonArray>();ids.add(ESPMANAGER_DEVICE_ID);d["device"]["name"]=ESPMANAGER_DEVICE_ID;String p;serializeJson(d,p);String t=String("homeassistant/")+e.t+"/"+ESPMANAGER_DEVICE_ID+"/"+e.id+"/config";mq.publish(t.c_str(),p.c_str(),true);}}void ESPManagerClass::connectMqtt(){if(mq.connected()||WiFi.status()!=WL_CONNECTED||millis()-lastMqtt<5000)return;lastMqtt=millis();String id=String("esp-")+ESPMANAGER_DEVICE_ID;bool ok=String(ESPMANAGER_MQTT_USER).length()?mq.connect(id.c_str(),ESPMANAGER_MQTT_USER,ESPMANAGER_MQTT_PASS,(base()+"/availability").c_str(),0,true,"offline"):mq.connect(id.c_str(),(base()+"/availability").c_str(),0,true,"offline");if(ok){mq.publish((base()+"/availability").c_str(),"online",true);mq.subscribe((base()+"/cmd/#").c_str());discover();}}void ESPManagerClass::begin(){Serial.begin(115200);WiFi.mode(WIFI_STA);WiFi.setAutoReconnect(true);wm.setConfigPortalBlocking(false);bool ok=wm.autoConnect((String("ESPManager-")+ESPMANAGER_DEVICE_ID).c_str());portal=!ok;if(!ok)lostAt=millis();mq.setServer(ESPMANAGER_MQTT_HOST,ESPMANAGER_MQTT_PORT);mq.setBufferSize(4096);mq.setCallback(rx);connectMqtt();}void ESPManagerClass::loop(){wm.process();if(WiFi.status()==WL_CONNECTED){if(portal){wm.stopConfigPortal();WiFi.softAPdisconnect(true);portal=false;WiFi.mode(WIFI_STA);}connectMqtt();mq.loop();return;}if(!lostAt)lostAt=millis();if(millis()-lastRetry>15000){lastRetry=millis();WiFi.mode(WIFI_AP_STA);WiFi.begin();}if(!portal&&millis()-lostAt>60000){wm.startConfigPortal((String("ESPManager-")+ESPMANAGER_DEVICE_ID).c_str());portal=true;}if(millis()-lostAt>900000)ESP.restart();}void ESPManagerClass::command(const String&t,const String&p){String pre=base()+"/cmd/entity/";if(t.startsWith(pre)&&handler)handler(t.substring(pre.length()),p);}void ESPManagerClass::log(const String&s){Serial.println(s);if(mq.connected())mq.publish((base()+"/log").c_str(),s.c_str());}
